from __future__ import annotations

import ast
from typing import Any, Union

import griffe


class AppendCheckedExtension(griffe.Extension):
    """Extension that appends ' [checked]' to every collected function's docstring."""

    def on_function_instance(
        self,
        *,
        node: Union[ast.AST, griffe.ObjectNode],
        func: griffe.Function,
        agent: Union[griffe.Visitor, griffe.Inspector],
        **kwargs: Any,
    ) -> None:
        suffix = " [checked]"
        if func.docstring is None:
            func.docstring = griffe.Docstring(suffix.strip(), parent=func)
        else:
            func.docstring.value = func.docstring.value + suffix


# Aggregate the extension the way griffe expects (Extensions container).
extensions = griffe.load_extensions(AppendCheckedExtension())

# Load "mypkg" through griffe's module-level entry point with the extension enabled.
package = griffe.load("mypkg", extensions=extensions)

if __name__ == "__main__":
    for module_name, module in package.modules.items():
        for func_name, func in module.functions.items():
            if func.docstring is not None:
                print(f"{module_name}.{func_name}: {func.docstring.value!r}")
